values ('portf-m02', 'build-your-student-portfolio', 'Show Your Work', 2, 'Show Your Work', 'SHOWWORK', array['Host work where it''s easy to open', 'Take clean screenshots', 'Write a short project summary', 'Share links safely and protect privacy']::text[], '{}'::text[])
