  "prompt": "A date dimension covering 1 January 2025 to 31 December 2026 has one row per day. How many rows does it have?",
  "answer": 730,
  "format": "number",
  "tolerance": 0,
  "hint": "Neither 2025 nor 2026 is a leap year.",
