  "format": "percent",
  "dataset": "agile",
  "files": ["backlog", "sprints"],
  "verify": "SELECT ROUND(100.0 * (SELECT SUM(points) FROM backlog WHERE status = 'Done' AND sprint = 5) / (SELECT committed_points FROM sprints WHERE sprint = 5), 1)",
