  "answer": 20.7,
  "format": "percent",
  "dataset": "process",
  "files": ["cases"],
  "verify": "SELECT ROUND(100.0 * SUM(importer_type = 'Pharmaceutical' AND docs_complete_on_arrival = 'No') / SUM(docs_complete_on_arrival = 'No'), 1) FROM cases WHERE checklist_pilot = 'No'",
