-- Track: Become a Data Scientist
insert into public.tracks (id, slug, title, summary, badge_name, badge_code, skills, position, published, programme_title, certificate_enabled)
values ('data-scientist', 'data-scientist', 'Become a Data Scientist', 'The route to a junior data scientist role. Build the analyst''s foundations (statistics, SQL and Python), then learn to build, test and explain machine learning models on realistic Nigerian business data, and to use them responsibly. Data science jobs ask for more than models: they ask for clean data, honest evaluation and results a business can act on, which is what this track teaches.', 'CloudTech Data Scientist', 'DATASCIENTIST', array['Statistics: distributions, confidence intervals and tests', 'Data wrangling in SQL and pandas', 'Regression and classification with scikit-learn', 'Cross-validation, tuning and honest evaluation', 'Cost-based decisions, explanation and fairness', 'Communicating models to non-technical decision-makers']::text[], 3, true, 'Data Science', true)
